  const sh = xtab_(tab, head), h = sh.getRange(1, 1, 1, head.length).getValues()[0];
  head.forEach((x, i) => { if (s_(h[i]) !== x) sh.getRange(1, i + 1).setValue(x).setFontWeight('bold'); });
  return sh;
}
function hoVidFolder_() {
  let id = setting_('Store task videos folder ID', '');
  if (id) { try { return DriveApp.getFolderById(id); } catch (e) { } }
  const f = DriveApp.createFolder(APP_NAME + ' – Store task videos'); setSetting_('Store task videos folder ID', f.getId()); return f;
}
/** d = {date, loc, shift, b64, mime, secs} */
